void check(bool result,const char* description){++checks;if(!result){++failures;std::cerr<<"FAIL "<<description<<'\n';}}
void require(const Status& result){if(!result.ok)throw std::runtime_error(result.error.original.code+":"+result.error.original.path);}
template<class T>T require(Outcome<T> result){if(!result.ok)throw std::runtime_error(result.error.original.code+":"+result.error.original.path);return std::move(result.value);}
